def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    count = sum(max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites)
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or not isfinite(volume) or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or not isfinite(v) or v <= 0 or count <= 0:
            return 0.0
        volume = v * count
    spheres = 0.0
    known = 0.0
    for site in sites:
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        o = max(0.0, site.get('occupancy', 1.0) or 0.0)
        if r is not None and isfinite(r) and r > 0:
            spheres += o * r * r * r
            known += o
    if known <= 0:
        return 0.0
    return (4.0 * pi / 3.0) * spheres * count / (known * volume)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    best = inf
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < len(sites) and 0 <= j < len(sites) and d > 0 and isfinite(d)):
            continue
        if (sites[i].get('occupancy', 1.0) or 0.0) <= 0 or (sites[j].get('occupancy', 1.0) or 0.0) <= 0:
            continue
        a = (props.get(sites[i].get('element')) or {}).get('covalent_radius_A')
        c = (props.get(sites[j].get('element')) or {}).get('covalent_radius_A')
        if a is not None and c is not None and isfinite(a) and isfinite(c) and a > 0 and c > 0:
            best = min(best, d / (a + c))
    return best if isfinite(best) else 0.0

