def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    nearest = [inf for x in sites]
    composition = {}
    for site in sites:
        e = site.get('element')
        composition[e] = composition.get(e, 0.0) + max(0.0, site.get('occupancy', 1.0) or 0.0)
    count = sum(composition.values())
    if count <= 0:
        return 0.0
    expected = 1.0 - sum((v / count) ** 2 for v in composition.values())
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and d > 0 and isfinite(d):
            if (sites[j].get('occupancy', 1.0) or 0.0) > 0:
                nearest[i] = min(nearest[i], d)
    total = 0.0
    weight = 0.0
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and d > 0 and isfinite(d) and isfinite(nearest[i]):
            if d <= 1.5 * nearest[i]:
                w = max(0.0, sites[i].get('occupancy', 1.0) or 0.0) * max(0.0, sites[j].get('occupancy', 1.0) or 0.0) * exp(-6.0 * (d / nearest[i] - 1.0))
                total += w * float(sites[i].get('element') != sites[j].get('element'))
                weight += w
    return total / weight - expected if weight > 0 else 0.0

