                nearest[i] = min(nearest[i], d)
    environments = [{} for x in sites]
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and d > 0 and isfinite(d) and isfinite(nearest[i]):
            if d <= 1.5 * nearest[i]:
                w = max(0.0, sites[j].get('occupancy', 1.0) or 0.0) * exp(-6.0 * (d / nearest[i] - 1.0))
                e = sites[j].get('element')
                environments[i][e] = environments[i].get(e, 0.0) + w
    total = 0.0
