            entropy = -sum((v / count) * log(v / count) for v in environments[i].values() if v > 0)
            o = max(0.0, sites[i].get('occupancy', 1.0) or 0.0)
            total += o * entropy
            weight += o
    return total / weight if weight > 0 else 0.0

